export declare const styles = "\n  :host {\n    \n  --_bg: var(--glass-bg, #f6f8f6);\n  --_fg: var(--glass-fg, #0d1310);\n  --_active: var(--glass-active, #1d8049);\n  --_highlight: var(--glass-highlight, rgba(255, 255, 255, 0.55));\n\n    position: sticky;\n    top: 0;\n    z-index: var(--glass-z, 50);\n    display: block;\n    height: 0;\n  }\n\n  :host([theme='dark']) {\n    \n  --_bg: var(--glass-bg, #0b0e0c);\n  --_fg: var(--glass-fg, #e9eeea);\n  --_active: var(--glass-active, #43c97e);\n  --_highlight: var(--glass-highlight, rgba(255, 255, 255, 0.06));\n\n  }\n\n  @media (prefers-color-scheme: dark) {\n    :host(:not([theme='light'])) {\n      \n  --_bg: var(--glass-bg, #0b0e0c);\n  --_fg: var(--glass-fg, #e9eeea);\n  --_active: var(--glass-active, #43c97e);\n  --_highlight: var(--glass-highlight, rgba(255, 255, 255, 0.06));\n\n    }\n  }\n\n  :host([hidden]) {\n    display: none;\n  }\n\n  *,\n  *::before,\n  *::after {\n    box-sizing: border-box;\n  }\n\n  .pill {\n    position: relative;\n    top: var(--glass-top, 14px);\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    width: min(var(--glass-max-width, 1148px), calc(100% - 24px));\n    min-height: 58px;\n    margin-inline: auto;\n    padding: 8px 8px 8px 20px;\n    border: 1px solid color-mix(in oklab, var(--_fg) 12%, transparent);\n    border-radius: 29px;\n    background: color-mix(in oklab, var(--_bg) 58%, transparent);\n    -webkit-backdrop-filter: blur(18px) saturate(160%);\n    backdrop-filter: blur(18px) saturate(160%);\n    box-shadow:\n      0 12px 32px -8px rgba(0, 0, 0, 0.28),\n      inset 0 1px 0 var(--_highlight);\n    color: var(--_fg);\n  }\n\n  .logo,\n  .cta {\n    display: flex;\n    flex: none;\n    align-items: center;\n    gap: 8px;\n  }\n\n  .logo {\n    min-width: 0;\n  }\n\n  .links {\n    position: relative;\n    isolation: isolate;\n    display: flex;\n    flex: 0 1 auto;\n    align-items: center;\n    gap: 2px;\n    min-width: 0;\n    margin-left: auto;\n    overflow: hidden;\n  }\n\n  .indicator {\n    position: absolute;\n    top: 0;\n    left: 0;\n    z-index: -1;\n    width: 0;\n    height: 0;\n    border-radius: 999px;\n    background: var(--glass-indicator, color-mix(in oklab, var(--_active) 12%, transparent));\n    opacity: 0;\n    pointer-events: none;\n    transition:\n      transform 0.55s cubic-bezier(0.2, 0.8, 0.2, 1),\n      width 0.55s cubic-bezier(0.2, 0.8, 0.2, 1),\n      height 0.55s cubic-bezier(0.2, 0.8, 0.2, 1),\n      opacity 0.3s ease;\n  }\n\n  .indicator.visible {\n    opacity: 1;\n  }\n\n  ::slotted(a) {\n    display: inline-flex;\n    flex: none;\n    align-items: center;\n    min-height: 36px;\n    padding: 0 12px;\n    border-radius: 999px;\n    color: color-mix(in oklab, var(--_fg) 72%, transparent);\n    font-size: 14px;\n    line-height: 1;\n    text-decoration: none;\n    white-space: nowrap;\n    transition: color 0.15s ease, background-color 0.15s ease;\n  }\n\n  ::slotted(a:hover) {\n    color: var(--_fg);\n  }\n\n  ::slotted(a[aria-current='true']) {\n    color: var(--_active);\n    transition: color 0.3s ease;\n  }\n\n  ::slotted(a:focus-visible) {\n    outline: 2px solid var(--_active);\n    outline-offset: 2px;\n  }\n\n  :host([wrapped]) .pill {\n    flex-wrap: wrap;\n    row-gap: 4px;\n    padding: 8px 8px 6px 16px;\n    border-radius: var(--glass-wrapped-radius, 20px);\n  }\n\n  :host([wrapped]) .cta {\n    margin-left: auto;\n  }\n\n  :host([wrapped]) .links {\n    order: 3;\n    flex: 1 1 100%;\n    margin: 0 -2px 0 -10px;\n    padding-top: 4px;\n    border-top: 1px solid color-mix(in oklab, var(--_fg) 8%, transparent);\n    overflow-x: auto;\n    scrollbar-width: none;\n  }\n\n  :host([wrapped]) .links::-webkit-scrollbar {\n    display: none;\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    .indicator {\n      transition: opacity 0.3s ease;\n    }\n  }\n\n  @supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n    .pill {\n      background: color-mix(in oklab, var(--_bg) 94%, transparent);\n    }\n  }\n";
